INSERT INTO categories (id, slug, name, description, image_url, sort_order, is_active, seo_title, seo_description)
VALUES
('a1000000-0000-0000-0000-000000000001', 'home-kitchen', 'Home & Kitchen', 'Elevated essentials designed for culinary precision and serene living spaces.', 'https://images.unsplash.com/photo-1556911220-e15b29be8c8f?auto=format&fit=crop&w=1000&q=80', 1, TRUE, 'Home & Kitchen - Premium Curated Living | MYCHOICE.in', 'Explore luxury pour-over kettles, aroma diffusers, and chef-grade kitchen essentials.'),
('a1000000-0000-0000-0000-000000000002', 'pet-supplies', 'Pet Supplies', 'Thoughtfully crafted accessories and wellness items for your beloved companions.', 'https://images.unsplash.com/photo-1548767797-d8c844163c4c?auto=format&fit=crop&w=1000&q=80', 2, TRUE, 'Pet Supplies - Modern Living for Pets | MYCHOICE.in', 'Discover orthopedic memory foam pet loungers, automated water fountains, and premium leashes.'),
('a1000000-0000-0000-0000-000000000003', 'beauty-personal-care', 'Beauty & Personal Care', 'Science-backed skincare tools and self-care rituals for radiant living.', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=1000&q=80', 3, TRUE, 'Beauty & Personal Care - Elevated Self Care | MYCHOICE.in', 'Shop sonic microcurrent facial devices, rose quartz rollers, and ionic hair stylers.'),
('a1000000-0000-0000-0000-000000000004', 'ornaments-fashion-accessories', 'Ornaments & Fashion Accessories', 'Refined jewelry, premium leather accents, and timeless personal adornments.', 'https://images.unsplash.com/photo-1599643478518-a784e5dc4c8f?auto=format&fit=crop&w=1000&q=80', 4, TRUE, 'Fashion Accessories & Fine Ornaments | MYCHOICE.in', '18K gold vermeil pendants, titanium rings, and Italian leather cardholders.'),
('a1000000-0000-0000-0000-000000000005', 'phone-tech-accessories', 'Phone & Tech Accessories', 'Sleek workspace hardware and magnetic wireless charging gear built for tomorrow.', 'https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?auto=format&fit=crop&w=1000&q=80', 5, TRUE, 'Phone & Tech Accessories - High-End Desk Gear | MYCHOICE.in', '3-in-1 magnetic wireless chargers, aluminum laptop stands, and braided 100W GaN cables.'),
('a1000000-0000-0000-0000-000000000006', 'fitness-wellness', 'Fitness & Wellness', 'High-performance recovery gear and active lifestyle essentials designed for vitality.', 'https://images.unsplash.com/photo-1518611012118-696072aa579a?auto=format&fit=crop&w=1000&q=80', 6, TRUE, 'Fitness & Wellness - Precision Recovery Tools | MYCHOICE.in', 'Deep tissue percussion massage guns, natural cork yoga mats, and smart resistance jump ropes.'),
('a1000000-0000-0000-0000-000000000007', 'eco-friendly-sustainable', 'Eco-Friendly & Sustainable', 'Consciously engineered zero-waste goods made from pure, earth-first materials.', 'https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&w=1000&q=80', 7, TRUE, 'Eco-Friendly & Sustainable Essentials | MYCHOICE.in', 'Vacuum ceramic tumblers, organic beeswax wraps, and wheat straw bento boxes.'),
('a1000000-0000-0000-0000-000000000008', 'baby-kids', 'Baby & Kids', 'Gentle, certified non-toxic essentials tailored for nurture and serene rest.', 'https://images.unsplash.com/photo-1519689680058-324335c77eba?auto=format&fit=crop&w=1000&q=80', 8, TRUE, 'Baby & Kids - Thoughtfully Pure Nursery Care | MYCHOICE.in', 'Silicone suction feeding sets, organic muslin swaddle blankets, and white noise sound machines.')
ON CONFLICT (id) DO NOTHING;

