-- 4. Insert 24 Curated Demo Products
INSERT INTO products (
    id, slug, name, short_description, description, category_id,
    brand_name, status, risk_status, featured, bestseller, new_arrival,
    seo_title, seo_description, base_currency, base_price, compare_at_price,
    cj_product_id, cj_product_sku, product_rating, review_count
) VALUES
('b2000000-0000-0000-0000-000000000001', 'minimalist-ultrasonic-aroma-diffuser', 'Minimalist Ultrasonic Aroma Diffuser & Ambient Light', 'Whisper-quiet ceramic ultrasonic diffuser with subtle ambient warm glow.', 'Sculpted from matte stone-finish ceramic, this ultrasonic diffuser purifies your atmosphere with micro-fine botanical mist while emitting a calm candle-like ambient illumination. Designed for modern living spaces requiring acoustic tranquility and understated elegance.', 'a1000000-0000-0000-0000-000000000001', 'MYCHOICE', 'published', 'normal', TRUE, TRUE, FALSE, 'Minimalist Ultrasonic Aroma Diffuser | MYCHOICE.in', 'Whisper-quiet ceramic aroma diffuser with gentle candle ambient lighting.', 'USD', 58.00, 78.00, 'CJ-HK-001', 'CJ-DIFF-CERAMIC', 4.9, 38),
('b2000000-0000-0000-0000-000000000002', 'precision-thermal-gooseneck-kettle', 'Precision Thermal Gooseneck Electric Pour-Over Kettle', 'Counter-balanced ergonomic pour-over kettle with 1-degree temperature control.', 'Engineered for specialty coffee enthusiasts and tea connoisseurs. Features a counter-balanced handle, 1-degree temperature precision dial, and a precision-fluted gooseneck spout that provides laminar, drip-free water flow control.', 'a1000000-0000-0000-0000-000000000001', 'MYCHOICE', 'published', 'normal', TRUE, FALSE, TRUE, 'Precision Gooseneck Pour-Over Kettle | MYCHOICE.in', 'Variable temperature electric pour-over kettle with flow-control gooseneck spout.', 'USD', 94.00, 125.00, 'CJ-HK-002', 'CJ-KET-GOOSE', 4.85, 42),
('b2000000-0000-0000-0000-000000000003', 'ergonomic-bamboo-prep-station', 'Solid Organic Bamboo Cutting & Culinary Prep Station', 'Multifunctional bamboo board with sliding stainless steel prep trays.', 'Crafted from end-grain organic Moso bamboo. Features deep juice perimeter grooves, silicone non-slip stabilizing feet, and integrated nesting food-grade stainless prep trays for effortless chopped ingredient segregation.', 'a1000000-0000-0000-0000-000000000001', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, FALSE, 'Bamboo Cutting & Prep Station | MYCHOICE.in', 'Organic bamboo cutting board with sliding stainless prep containers.', 'USD', 46.00, 62.00, 'CJ-HK-003', 'CJ-BRD-PREP', 4.8, 29),
('b2000000-0000-0000-0000-000000000004', 'orthopedic-memory-foam-pet-lounger', 'Orthopedic Memory Foam Calming Pet Lounger', 'Human-grade dual density orthopedic foam with removable velvet faux-fur cover.', 'Engineered to alleviate joint stress in both growing pups and mature companions. The contoured supportive bolster rim provides neck alignment, while the memory foam core cushions pressure points. Waterproof inner lining with machine-washable outer velvet cover.', 'a1000000-0000-0000-0000-000000000002', 'MYCHOICE', 'published', 'normal', TRUE, TRUE, FALSE, 'Orthopedic Memory Foam Pet Lounger | MYCHOICE.in', 'Luxury orthopedic calming dog and cat bed with supportive memory foam bolsters.', 'USD', 68.00, 89.00, 'CJ-PET-001', 'CJ-BED-ORTHO', 4.92, 54),
('b2000000-0000-0000-0000-000000000005', 'stainless-steel-pet-water-fountain', 'Ultra-Quiet Stainless Steel Circulating Pet Fountain', 'Hygienic 304 food-grade stainless steel with quad-action charcoal filtration.', 'Veterinarian-recommended stainless construction eliminates chin acne caused by plastic bowls. Constant aerobic aeration provides crisp, oxygenated stream water that encourages optimal hydration in cats and small dogs.', 'a1000000-0000-0000-0000-000000000002', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, TRUE, 'Stainless Steel Pet Water Fountain | MYCHOICE.in', 'Hygienic quiet pet water fountain with 4-stage carbon filtration.', 'USD', 39.00, 52.00, 'CJ-PET-002', 'CJ-FOUNTAIN-SS', 4.88, 31),
('b2000000-0000-0000-0000-000000000006', 'hands-free-bungee-dog-leash', 'Tactical Shock-Absorbing Hands-Free Running Leash', 'Dual-handle shock-absorbing bungee leash with reflective 3M safety threads.', 'Designed for active outdoor owners. Wear comfortably around your waist during jogs or use the secondary neoprene traffic handle for instant close-quarters control in busy urban streets. Absorbs sudden pulls up to 150 lbs.', 'a1000000-0000-0000-0000-000000000002', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, FALSE, 'Hands-Free Running Dog Leash | MYCHOICE.in', 'Dual handle bungee shock-absorbing running leash with reflective safety stitching.', 'USD', 28.00, 38.00, 'CJ-PET-003', 'CJ-LEASH-BUNGEE', 4.79, 22),
('b2000000-0000-0000-0000-000000000007', 'sonic-microcurrent-facial-device', 'SculptPro Sonic Microcurrent Facial Toning Device', 'Non-invasive anti-aging facial lifting tool with red light therapy.', 'Replicate professional clinical facial contouring at home. Gentle microcurrent impulses stimulate facial muscles to visibly firm, tone, and lift the jawline and brow area while 630nm red phototherapy boosts natural collagen synthesis.', 'a1000000-0000-0000-0000-000000000003', 'MYCHOICE', 'published', 'normal', TRUE, TRUE, FALSE, 'Sonic Microcurrent Facial Toning Device | MYCHOICE.in', 'Clinical grade microcurrent facial toning device with 630nm red light therapy.', 'USD', 89.00, 120.00, 'CJ-BPC-001', 'CJ-DEV-MICRO', 4.94, 67),
('b2000000-0000-0000-0000-000000000008', 'rose-quartz-sculpting-roller', 'Grade-A Rose Quartz Lymphatic Sculpting & Gua Sha Duo', 'Handcrafted 100% natural Brazilian rose quartz facial roller and contoured scraper.', 'Carved from premium Brazilian rose quartz crystal. Regular use calms facial puffiness, facilitates lymphatic fluid drainage, and improves serum absorption for an instant lit-from-within glow.', 'a1000000-0000-0000-0000-000000000003', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, FALSE, 'Rose Quartz Gua Sha & Sculpting Roller | MYCHOICE.in', 'Authentic Brazilian natural rose quartz facial roller and gua sha set.', 'USD', 32.00, 45.00, 'CJ-BPC-002', 'CJ-SET-QUARTZ', 4.87, 34),
('b2000000-0000-0000-0000-000000000009', 'negative-ion-ionic-hair-styler', 'AeroSilk Negative Ion High-Speed Hair Styler & Dryer', '110,000 RPM brushless motor with 200 million negative ions for zero frizz.', 'Engineered with intelligent thermal monitoring sensors measuring air temperature 50 times per second to prevent heat damage. High-density negative ion flow seals hair cuticles for mirror-like shine in half the drying time.', 'a1000000-0000-0000-0000-000000000003', 'MYCHOICE', 'published', 'normal', TRUE, FALSE, TRUE, 'High-Speed Ionic Hair Dryer | MYCHOICE.in', 'Brushless motor negative ion hair dryer with smart thermostatic heat guard.', 'USD', 119.00, 169.00, 'CJ-BPC-003', 'CJ-DRY-IONIC', 4.91, 45),
('b2000000-0000-0000-0000-000000000010', '18k-gold-vermeil-geometric-pendant', 'Aura 18K Gold Vermeil Geometric Compass Pendant', 'Thick 2.5 micron 18K gold over 925 sterling silver with ethical lab sapphire.', 'An homage to timeless seafaring navigation. Crafted in heavy 18 karat gold vermeil over a certified solid 925 sterling silver foundation. Features a faceted center white sapphire that catches natural daylight with subtle brilliance.', 'a1000000-0000-0000-0000-000000000004', 'MYCHOICE', 'published', 'normal', TRUE, TRUE, FALSE, '18K Gold Vermeil Geometric Compass Pendant | MYCHOICE.in', 'Luxury 18K gold vermeil compass pendant with lab sapphire accent.', 'USD', 72.00, 98.00, 'CJ-OFA-001', 'CJ-JW-COMPASS', 4.96, 48),
('b2000000-0000-0000-0000-000000000011', 'minimalist-ceramic-titanium-ring', 'Architectural Zirconia Ceramic & Aerospace Titanium Band', 'Ultra-scratch resistant black zirconia ceramic band with titanium inner core.', 'Engineered comfort-fit ring uniting matte industrial black zirconia ceramic with a brushed aerospace-grade Grade-5 titanium core. Incredibly lightweight, scratch-impervious, and completely hypoallergenic.', 'a1000000-0000-0000-0000-000000000004', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, TRUE, 'Ceramic & Titanium Unisex Ring Band | MYCHOICE.in', 'Scratch-resistant zirconia ceramic and titanium architectural ring.', 'USD', 52.00, 70.00, 'CJ-OFA-002', 'CJ-RNG-TITAN', 4.86, 19),
('b2000000-0000-0000-0000-000000000012', 'italian-leather-slim-rfid-cardholder', 'Artisan Full-Grain Italian Leather RFID Card Wallet', 'Slim handcrafted vegetable-tanned Italian leather with RFID signal block.', 'Hand-stitched by leather artisans using full-grain Tuscan vegetable-tanned cowhide. Houses up to 8 cards with quick-access thumb pull-tab and folded bill compartment, all protected by a woven RFID electromagnetic shield.', 'a1000000-0000-0000-0000-000000000004', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, FALSE, 'Italian Leather Slim RFID Cardholder | MYCHOICE.in', 'Full grain vegetable-tanned Italian leather minimalist cardholder with RFID protection.', 'USD', 44.00, 60.00, 'CJ-OFA-003', 'CJ-WLT-SLIM', 4.88, 37),
('b2000000-0000-0000-0000-000000000013', '3-in-1-magnetic-wireless-charging-station', 'MagFold 3-in-1 Magnetic Fast Wireless Charging Dock', 'Ultra-compact foldable aluminum station for iPhone, Apple Watch, and AirPods.', 'Declutter your nightstand or workspace with this CNC machined aerospace aluminum wireless station. Strong N52 neodymium magnets snap phone securely into portrait or landscape StandBy orientation while delivering up to 15W Qi2 fast charging.', 'a1000000-0000-0000-0000-000000000005', 'MYCHOICE', 'published', 'normal', TRUE, TRUE, FALSE, '3-in-1 Foldable Magnetic Wireless Charging Station | MYCHOICE.in', 'Premium aluminum 3-in-1 foldable Qi2 magnetic wireless charger.', 'USD', 69.00, 95.00, 'CJ-PTA-001', 'CJ-CHG-MAG3', 4.93, 82),
('b2000000-0000-0000-0000-000000000014', 'aerospace-aluminum-laptop-stand', 'Architectural CNC Aluminum Laptop & Tablet Riser', 'Ergonomic 360-degree rotating dual-axis aluminum riser for 10-17 inch laptops.', 'Eliminate neck strain with a dual-hinge architectural aluminum stand. Features a satisfying mechanical click 360-degree rotating base, vented heat dissipation ports, and reinforced dampers supporting up to 10 kg without sagging.', 'a1000000-0000-0000-0000-000000000005', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, TRUE, 'Architectural Aluminum Laptop Riser Stand | MYCHOICE.in', 'Heavy duty 360 rotating dual-hinge laptop stand in matte aluminum.', 'USD', 48.00, 65.00, 'CJ-PTA-002', 'CJ-STND-ALUM', 4.88, 39),
('b2000000-0000-0000-0000-000000000015', 'ultra-slim-braided-100w-gan-cable-kit', 'ArmorFlex 100W GaN Fast Charge Braided Cable Duo', 'E-marker chipped Kevlar-reinforced 100W USB-C cable set with silicone organizers.', 'Engineered to outlast standard OEM cables by 10x. Built with high-density ballistic nylon braiding, integrated E-Marker chipset for smart power regulation up to 100W, and gold-plated terminal contacts for rapid power delivery.', 'a1000000-0000-0000-0000-000000000005', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, FALSE, '100W GaN Braided USB-C Cable Duo | MYCHOICE.in', 'Kevlar braided 100W fast charge USB-C cable kit with E-marker chip.', 'USD', 24.00, 35.00, 'CJ-PTA-003', 'CJ-CBL-100W', 4.82, 26),
('b2000000-0000-0000-0000-000000000016', 'deep-tissue-percussion-massage-gun', 'PulsePro Deep Tissue Percussion Therapy Massage Device', '12mm deep amplitude recovery tool with whisper-glide quiet motor.', 'Designed in collaboration with physical therapists. Delivers 12mm penetrative stroke amplitude targeting deep muscle knots, accelerating post-workout lactic acid clearance, and alleviating chronic myofascial tension.', 'a1000000-0000-0000-0000-000000000006', 'MYCHOICE', 'published', 'normal', TRUE, TRUE, FALSE, 'Deep Tissue Percussion Massage Gun | MYCHOICE.in', 'Professional 12mm amplitude percussion therapy massage gun with 5 heads.', 'USD', 84.00, 115.00, 'CJ-FIT-001', 'CJ-GUN-PERC', 4.95, 71),
('b2000000-0000-0000-0000-000000000017', 'non-slip-natural-cork-yoga-mat', 'AuraEarth Non-Slip Organic Cork & Tree Rubber Yoga Mat', 'Antimicrobial sustainable cork surface with natural rubber grip foundation.', 'Experience grounding naturally. Organic harvested cork gains superior grip the more you sweat, while the 4.5mm natural tree rubber base anchors firmly to studio hardwood without bunching. Contains zero PVC, phthalates, or toxic glues.', 'a1000000-0000-0000-0000-000000000006', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, TRUE, 'Organic Cork & Tree Rubber Yoga Mat | MYCHOICE.in', 'Naturally antimicrobial non-slip organic cork yoga mat with laser body alignment lines.', 'USD', 56.00, 75.00, 'CJ-FIT-002', 'CJ-MAT-CORK', 4.89, 38),
('b2000000-0000-0000-0000-000000000018', 'smart-digital-resistance-jump-rope', 'OrbitPulse Smart Digital Weighted Jump Rope', 'Dual-mode cordless and steel-cable smart jump rope with Bluetooth tracking.', 'Switch seamlessly between outdoor 3-meter steel cable jumping and indoor silent cordless weighted balls. Built-in dual hall sensors accurately track your rotations, calorie burn, and workout duration on an integrated backlit LED display.', 'a1000000-0000-0000-0000-000000000006', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, FALSE, 'Smart Digital Weighted Jump Rope | MYCHOICE.in', 'Dual-mode cordless and cable smart jump rope with LCD rotation counter.', 'USD', 34.00, 48.00, 'CJ-FIT-003', 'CJ-RPE-SMART', 4.77, 24),
('b2000000-0000-0000-0000-000000000019', 'insulated-ceramic-travel-tumbler', 'PureTaste Double-Wall Ceramic Lined Travel Tumbler', 'Vacuum-insulated stainless tumbler with true ceramic interior lining.', 'Say goodbye to metallic coffee aftertaste. Featuring a true porcelain ceramic interior coating bonded to a double-wall vacuum stainless exterior. Keeps cold brew chilled for 24 hours and piping hot espresso warm for 12 hours.', 'a1000000-0000-0000-0000-000000000007', 'MYCHOICE', 'published', 'normal', TRUE, TRUE, FALSE, 'Ceramic Lined Vacuum Travel Tumbler | MYCHOICE.in', 'Vacuum insulated stainless steel tumbler with pure ceramic interior.', 'USD', 38.00, 50.00, 'CJ-ECO-001', 'CJ-TUM-CERAM', 4.92, 46),
('b2000000-0000-0000-0000-000000000020', 'zero-waste-organic-beeswax-wraps', 'Artisan Organic Beeswax Food Storage Wraps (Pack of 5)', 'Zero-waste reusable breathable wraps made from organic cotton and jojoba oil.', 'Replace single-use plastic cling wrap forever. Hand-dipped in organic beeswax, sustainably harvested tree resin, and cold-pressed jojoba oil. Warm with the heat of your hands to seal over bowls, cheese, fresh sourdough, and produce.', 'a1000000-0000-0000-0000-000000000007', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, FALSE, 'Organic Beeswax Reusable Food Wraps | MYCHOICE.in', 'Pack of 5 zero waste organic beeswax and jojoba oil food wraps.', 'USD', 22.00, 32.00, 'CJ-ECO-002', 'CJ-WRP-BEES', 4.84, 31),
('b2000000-0000-0000-0000-000000000021', 'natural-wheat-straw-bento-lunch-box', 'Kanso Minimalist Natural Wheat Straw Bento Lunch Box', 'Plant-fiber dual layer meal prep box with wooden cutlery set.', 'Crafted from upcycled reclaimed wheat straw fibers. Features two stackable leak-proof compartments, removable portion dividers, and a snug silicone airtight seal held firmly by an elastic canvas band. Comes with matching reusable utensils.', 'a1000000-0000-0000-0000-000000000007', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, TRUE, 'Natural Wheat Straw Bento Box | MYCHOICE.in', 'Eco-friendly natural wheat straw fiber bento lunch box with cutlery set.', 'USD', 26.00, 36.00, 'CJ-ECO-003', 'CJ-BENTO-WHEAT', 4.81, 22),
('b2000000-0000-0000-0000-000000000022', 'silicone-suction-feeding-set', 'PureSilicone Toddler Feeding & Self-Weaning Set (6-Piece)', '100% food-grade platinum silicone suction plate, bowl, cup, bib, and spoons.', 'Designed to encourage independent toddler self-feeding without the messy spills. Powerful suction bases anchor plate and bowl securely to high chair trays. Soft flexible silicone protects tender gums while resisting stains and odors.', 'a1000000-0000-0000-0000-000000000008', 'MYCHOICE', 'published', 'normal', TRUE, TRUE, FALSE, 'Silicone Suction Baby Feeding Set | MYCHOICE.in', 'Platinum food grade silicone suction plate, bowl, bib, and spoon set.', 'USD', 36.00, 49.00, 'CJ-BK-001', 'CJ-SET-FEEDING', 4.96, 58),
('b2000000-0000-0000-0000-000000000023', 'organic-muslin-cotton-swaddle-bundle', 'CloudSoft GOTS Organic Muslin Swaddle Blanket Bundle (3-Pack)', 'Ultra-breathable 100% GOTS certified organic muslin cotton swaddles.', 'Woven from extra-long staple certified organic Turkish cotton. The airy open weave regulates baby body temperature to prevent overheating, while getting softer and fluffier with every laundering. Generous 47x47 inch dimensions allow secure swaddling.', 'a1000000-0000-0000-0000-000000000008', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, TRUE, 'Organic Muslin Cotton Swaddle Bundle | MYCHOICE.in', 'Set of 3 extra-large GOTS organic muslin cotton baby swaddles.', 'USD', 38.00, 52.00, 'CJ-BK-002', 'CJ-SWD-ORGANIC', 4.93, 41),
('b2000000-0000-0000-0000-000000000024', 'portable-white-noise-sound-machine', 'LullabyAcoustic Portable White Noise Machine & Night Light', '24 soothing acoustic profiles with breathable warm amber night light.', 'Engineered to promote deep infant circadian rhythms. Houses 24 non-looping high-fidelity nature sounds and pink/brown noise frequencies that mask household disruptions. Compact rechargeable design clips conveniently to strollers or crib rails.', 'a1000000-0000-0000-0000-000000000008', 'MYCHOICE', 'published', 'normal', FALSE, FALSE, FALSE, 'Portable White Noise Sound Machine | MYCHOICE.in', 'Rechargeable sound machine with 24 non-looping sounds and warm amber night light.', 'USD', 42.00, 58.00, 'CJ-BK-003', 'CJ-SND-NOISE', 4.88, 35)
ON CONFLICT (id) DO NOTHING;

